class Solution {
public:
    int minimumPushes(string word) {
        int freq[26] = {0};
        for (char c : word) {
            freq[c - 'a']++;
        }
        sort(freq, freq + 26, greater<int>());
        int total = 0;
        for (int i = 0; i < 26; i++) {
            total += freq[i] * (i / 8 + 1);
        }
        return total;
    }
};
